open(p,'w').write("def transform(grid):
    h, w = len(grid), len(grid[0])
    for r,row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            a, b = grid[:r], grid[r+1:]
            n=min(len(a),len(b))
            return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0 for j in range(w)] for i in range(n)]
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            return [[2 if grid[r][j] != 0 and grid[r][j+c+1] != 0 else 0 for j in range(min(c,w-c-1))] for r in range(h)]
    raise ValueError('separator missing')
")
